			array( 'בית המשפט לענייני משפחה מוסמך בתביעה בין אדם או עזבונו לבין בן משפחתו, לרבות הידועה בציבור כאשתו', 'https://he.wikisource.org/wiki/חוק_בית_המשפט_לעניני_משפחה', 'חוק בית המשפט לענייני משפחה, סעיף 1(2)' ),
			array( 'בתי המשפט הכירו בזכויות ירושה של בני זוג מאותו מין בדומה לידועים בציבור, אך בהיעדר הכרעה של בית המשפט העליון אין הלכה מחייבת, ולכן כל זכות ממליץ לערוך צוואה', 'https://www.kolzchut.org.il/he/ירושה_של_בן_זוג_מאותו_מין', 'כל זכות' ),
			array( 'הסכם בדבר ירושתו של אדם וויתור על ירושתו שנעשו בחייו בטלים, ולכן הסדרת הירושה בין ידועים בציבור נעשית בצוואה ולא בהסכם חיים משותפים', 'https://he.wikisource.org/wiki/חוק_הירושה', 'חוק הירושה, סעיף 8' ),
		),
		'official'  => array(
			array( 'ירושה של ידוע או ידועה בציבור, כל זכות', 'https://www.kolzchut.org.il/he/ירושה_של_ידוע/ה_בציבור' ),
			array( 'חוק הירושה, סעיפים 55 ו-57', 'https://he.wikisource.org/wiki/חוק_הירושה' ),
			array( 'ירושה של בן זוג מאותו מין, כל זכות', 'https://www.kolzchut.org.il/he/ירושה_של_בן_זוג_מאותו_מין' ),
		),
		'sections'  => array(
			array( 'h' => 'שלושת התנאים', 'p' => 'סעיף 55 דורש שלושה דברים במצטבר: בני הזוג חיו חיי משפחה במשק בית משותף; בשעת המוות איש מהם לא היה נשוי לאדם אחר; והמוריש לא הותיר צוואה שקובעת אחרת, במפורש או במשתמע. כשהתנאים מתקיימים, הנשאר בחיים מקבל בדיוק את מה שסעיף 11 נותן לבן זוג נשוי: המיטלטלין והמכונית, מחצית לצד ילדים או הורים, שני שלישים לצד אחים או סבים, והכול כשאין קרובים. לפי כל זכות מגישים בקשה לצו ירושה רגילה, ובן הזוג מוכיח בה את החיים המשותפים.' ),
			array( 'h' => 'איפה המנגנון שונה', 'p' => 'החוק מכנה את ההסדר מעין צוואה, ולכן הזכות היא של זוכה על פי צוואה ולא של יורש על פי דין, והצוואה של המנוח גוברת עליה. סעיף 57(ג) משלים את התמונה ומעניק לידוע בציבור גם זכות למזונות מן העיזבון. מי שעדיין נשוי לאדם אחר, גם אם נפרד ממנו שנים, אינו נכנס לסעיף. הסכם לחיים משותפים אינו תחליף, כי סעיף 8 מבטל הסכמי ירושה בחיי המוריש. לפי כל זכות, לבני זוג מאותו מין אין עדיין הלכה מחייבת, וצוואה היא הדרך הבטוחה.' ),
		),
