		'title'     => 'ירושה מכוח אימוץ: מה יורש המאומץ, מה יורש המאמץ ומי לא',
		'seo_title' => 'ירושה מכוח אימוץ לפי סעיף 16 לחוק הירושה | Jus-Tice',
		'seo_desc'  => 'סעיף 16 לחוק הירושה: המאומץ יורש את מאמצו כילדו, המאמץ יורש את המאומץ כהורהו, והמאומץ יורש גם את קרובי המאמץ מאז 2012. הוריו הביולוגיים אינם יורשים.',
		'intro'     => 'אימוץ מנתק ומחבר בבת אחת. החוק מעמיד את המאומץ במקום ילד ביולוגי כלפי המאמץ ומשפחתו, ומשאיר לו זכות לרשת את קרוביו הביולוגיים, אבל סוגר את הדלת בכיוון ההפוך: ההורים הביולוגיים אינם יורשים את המאומץ.',
		'facts'     => array(
			array( 'מי שאומץ כדין יורש את מאמצו כאילו היה ילדו, וצאצאי המאומץ יורשים את המאמץ; המאמץ יורש את המאומץ כאילו היה הורהו', 'https://he.wikisource.org/wiki/חוק_הירושה', 'חוק הירושה, סעיף 16(א)' ),
			array( 'המאומץ וצאצאיו זוכים על פי דין בעיזבונם של קרובי המאמץ כאילו היו יורשים, וקרובי המאמץ זוכים בעיזבונו של המאומץ', 'https://he.wikisource.org/wiki/חוק_הירושה', 'חוק הירושה, סעיף 16(ב)' ),
			array( 'המאומץ וצאצאיו יורשים את קרובי המאומץ, אולם הורי המאומץ והורי הוריו וצאצאיהם אינם יורשים את המאומץ', 'https://he.wikisource.org/wiki/חוק_הירושה', 'חוק הירושה, סעיף 16(ג)' ),
			array( 'הזכות ההדדית בין המאומץ לקרובי המאמץ נוספה בתיקון לחוק שתוקפו מיום 23.07.2012', 'https://www.kolzchut.org.il/he/ירושה_במקרה_של_אימוץ', 'כל זכות' ),
			array( 'לעניין מזונות מן העיזבון, ילד כולל ילד מאומץ', 'https://he.wikisource.org/wiki/חוק_הירושה', 'חוק הירושה, סעיף 57(ד)' ),
		),
		'official'  => array(
