			array( 'חוק הירושה, סעיף 16', 'https://he.wikisource.org/wiki/חוק_הירושה' ),
			array( 'יורשים על פי דין, כל זכות', 'https://www.kolzchut.org.il/he/יורשים_על_פי_דין' ),
		),
		'sections'  => array(
			array( 'h' => 'מה המאומץ יורש', 'p' => 'סעיף 16(א) משווה את המאומץ לילד: הוא יורש את מאמצו בחלק שווה לילדים האחרים, וצאצאיו נכנסים במקומו לפי כלל החליפים. סעיף 16(ב), שנוסף בתיקון משנת 2012, הרחיב את המעגל: המאומץ וצאצאיו יורשים גם את קרובי המאמץ, למשל סב מאמץ או אח של המאמץ שנפטר בלי ילדים, בדיוק כאילו היו קרובי דם. סעיף 16(ג) משאיר למאומץ גם את הזכות לרשת את קרוביו הביולוגיים, כך שהאימוץ מוסיף מעגל ירושה ואינו גורע.' ),
			array( 'h' => 'מי יורש את המאומץ', 'p' => 'בכיוון ההפוך החוק סלקטיבי. המאמץ יורש את המאומץ כאילו היה הורהו, וקרובי המאמץ יורשים אותו כקרובים לכל דבר. לעומת זאת הוריו הביולוגיים של המאומץ, הורי הוריו וצאצאיהם אינם יורשים אותו כלל, גם אם אין לו יורשים אחרים; במקרה כזה העיזבון עובר למדינה לפי סעיף 17. לפי כל זכות, ההיגיון הוא למנוע הטלת זכויות וחובות על המשפחה הביולוגית שהקשר עמה נותק. לעניין מזונות מן העיזבון סעיף 57(ד) כולל במפורש ילד מאומץ.' ),
		),
