	array(
		'slug'      => 'bureaus-districts-estate-registrar',
		'title'     => 'לשכות הרשם לענייני ירושה: חמישה מחוזות, מוקד 2416 והמערכת המקוונת',
		'seo_title' => 'מחוזות הרשם לענייני ירושה ואיתור המחוז המטפל | Jus-Tice',
		'seo_desc'  => 'לשכות בירושלים, תל אביב, חיפה, נוף הגליל ובאר שבע, המחוז נקבע לפי מושבו האחרון של המנוח, קבלת קהל בזימון תור, מוקד 2416 כוכבית והמערכת המקוונת.',
		'intro'     => 'הרשם לענייני ירושה אינו כתובת אחת אלא חמש לשכות מחוזיות תחת ממונה ארצי. המחוז נקבע לפי מקום מושבו האחרון של המנוח, ורוב הפעולות נעשות מרחוק, במערכת המקוונת ובמוקד הטלפוני.',
		'facts'     => array(
			array( 'האפוטרופוס הכללי הוא הממונה הארצי לענייני ירושה, סגניו הכשירים לשופט שלום הם רשמים לענייני ירושה, ושר המשפטים קובע ברשומות את אזורי פעולתם', 'https://he.wikisource.org/wiki/חוק_הירושה', 'חוק הירושה, סעיף 65א' ),
			array( 'לשכות הרשמים לענייני ירושה נמצאות בבאר שבע, חיפה, ירושלים, נוף הגליל ותל אביב, והן יחידות באגף האפוטרופוס הכללי במשרד המשפטים', 'https://www.kolzchut.org.il/he/הרשם_לענייני_ירושה', 'כל זכות' ),
			array( 'הבקשה מוגשת לרשם שבאזור פעולתו היה מושבו של המוריש במותו, והממונה הארצי רשאי להורות על העברתה לאזור אחר כשרוב המבקשים גרים מחוצה לו', 'https://he.wikisource.org/wiki/תקנות_הירושה', 'תקנות הירושה, תקנה 13' ),
			array( 'מרכז השירות והמידע: 2416 כוכבית, מענה אנושי בימים ראשון עד חמישי בין 8:00 ל-16:00 בשלוחה 7, ומענה 24 שעות בשלוחה 3; קבלת קהל בימי שני ורביעי בזימון תור', 'https://www.gov.il/he/service/inheritance_order', 'בקשה למתן צו ירושה, השירות הממשלתי' ),
			array( 'המערכת המקוונת מאפשרת לאתר בקשות ומצבן, לבדוק קיום בקשה על מנוח ברשם, בבתי הדין הרבניים ובבתי המשפט, ולהגיש השלמות, התנגדויות ובקשות בתיק', 'https://inheritance.justice.gov.il/', 'הרשם לענייני ירושה, המערכת המקוונת' ),
			array( 'הממונה הארצי מנהל מרשם ארצי של צווי ירושה וצווי קיום, של בקשות ושל צוואות שהופקדו', 'https://he.wikisource.org/wiki/חוק_הירושה', 'חוק הירושה, סעיף 73ד' ),
		),
		'official'  => array(
			array( 'האפוטרופוס הכללי והממונה על ענייני ירושה, השירות הממשלתי', 'https://www.gov.il/he/departments/agor_ministry_of_justice' ),
			array( 'המערכת המקוונת של הרשם לענייני ירושה', 'https://inheritance.justice.gov.il/' ),
			array( 'הרשם לענייני ירושה, כל זכות', 'https://www.kolzchut.org.il/he/הרשם_לענייני_ירושה' ),
		),
		'sections'  => array(
			array( 'h' => 'איך בנוי המערך ואיך מוצאים את המחוז', 'p' => 'סעיף 65א מעמיד בראש המערך את האפוטרופוס הכללי כממונה ארצי לענייני ירושה, וסגניו הכשירים לכהן כשופטי שלום הם הרשמים. אזורי הפעולה נקבעים בהודעה ברשומות, ולפי כל זכות הלשכות פועלות בירושלים, תל אביב, חיפה, נוף הגליל ובאר שבע. תקנה 13 קובעת שהמחוז המטפל הוא זה שבו היה מושבו של המנוח במותו, ומי שגר בחוץ לארץ מגיש במחוז שבו נמצאים הנכסים. השירות הממשלתי מעמיד כלי לאיתור המחוז לפי היישוב, והממונה הארצי רשאי להעביר תיק למחוז אחר כשרוב המבקשים גרים הרחק ממנו.' ),
			array( 'h' => 'איך פונים בפועל', 'p' => 'רוב הפעולות אינן דורשות הגעה: הבקשות לצו מוגשות במערכת המקוונת, השלמות מסמכים, התנגדויות, בקשות למינוי מנהל עיזבון, לתיקון צו, להעתק צו ולעיון בתיק מוגשות דרך לשונית איתור בקשות, וכל בקשה שהוגשה מוצגת לעיון הציבור. המוקד 2416 כוכבית משיב אנושית בימים ראשון עד חמישי בין 8:00 ל-16:00, ומידע אוטומטי זמין כל היממה. קבלת קהל למי שאינו מיוצג מתקיימת בימי שני ורביעי בזימון תור מראש, וקיימת גם לשכה בראשון לציון להפקדת צוואות. הפקדת צוואה ועריכת צוואה בפני הרשם מחייבות התייצבות.' ),
