			array( 'במקרים המנויים בתוספת השנייה מנהל העיזבון מגיש את הפרטה, השומה והדוחות גם לאפוטרופוס הכללי לשם בדיקתם', 'https://he.wikisource.org/wiki/חוק_הירושה', 'חוק הירושה, סעיף 87' ),
