		'official'  => array(
			array( 'פטור ממס שבח במכירת דירה שהתקבלה בירושה, כל זכות', 'https://www.kolzchut.org.il/he/פטור_ממס_שבח_במכירת_דירה_שהתקבלה_בירושה' ),
